import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"交易时间对成交量时间","description":"","frontmatter":{"title":"交易时间对成交量时间","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/business-time-clock.md","filePath":"quant/business-time-clock.md","lastUpdated":1789023840000}'),c={name:"quant/business-time-clock.md"};function p(A,a,m,u,b,B){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="交易时间对成交量时间" tabindex="-1">交易时间对成交量时间 <a class="header-anchor" href="#交易时间对成交量时间" aria-label="Permalink to &quot;交易时间对成交量时间&quot;">​</a></h1><div class="epigraph"><p>墙钟上波动的季节与聚集，有一部分只是「忙的时候事件密」；把时间按累计成交量（或交易次数）重新标度，价格增量可以接近较齐的过程。</p><footer>—— Mandelbrot and Taylor, On the Distribution of Stock Price Differences, Operations Research, 1967；Clark, A Subordinated Stochastic Process Model, Econometrica, 1973；Ané and Geman, Order Flow, Transaction Clock, and Normality of Asset Returns, Journal of Finance, 2000</footer></div><p><a href="/quant/point-process-durations">点过程</a> 在墙钟 \\(t\\) 上估强度 \\(\\lambda(t)\\)。从属过程把日历时间换成业务时间 \\(\\theta\\)：价格 \\(X_t=W_{\\theta(t)}\\)，\\(\\theta\\) 随交易活动增。Clark 用交易次数从属解释收益峰度；Ané–Geman 用成交量时钟让收益更接近条件正态。本课缺口：采样方案本身（<a href="/quant/tick-bars">tick bars</a>、<a href="/quant/dollar-bars">dollar bars</a>）是业务时间的离散实现，会改变 RV、噪声与季节的外观。最后一课把预测损失定义在你选定的时钟上——时钟一换，QLIKE 的对象跟着换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>墙钟五分钟：开盘格信息多、午间少，同 \\(\\Delta t\\) 不同质。业务时间：每发生 \\(V\\) 的成交额（或 \\(N\\) 笔、或 \\(Q\\) 股）封一根，使每根的「活动量」齐。问题是 \\(\\theta\\) 的选择：笔数、股数、金额、还是经验累积 \\(|r|\\)。Mandelbrot–Taylor 的交易时间、Clark 的从属、López de Prado 的 bars 是同一思想的不同工程。</p><p>对象：让增量更齐次，以便 GARCH/RV/正态近似更好用。不是发现新 alpha。换时钟不能把噪声变没——繁忙段 \\(n\\) 仍大，只是被并进更少的「业务格」。</p><h3 id="与日内季节" tabindex="-1">与日内季节 <a class="header-anchor" href="#与日内季节" aria-label="Permalink to &quot;与日内季节&quot;">​</a></h3><p>去季节 \\(s_i\\) 是在墙钟格上除确定性尺度。业务时间是把格本身拉长缩短。两者都在对付 U 形，机制不同：一个除权，一个重采样。叠用要声明，否则双重补偿。期货全球会话的「忙」按产品，金额时钟更跨会话可比。</p><p><span class="marginnote">成交量时钟在价格趋势里：同样股数的名义风险随价格变，dollar bars 更齐，见已有 dollar bars 课。本课给计量动机：从属过程与正态化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>构造。</strong> 累计 \\(q_i\\) 或 \\(p_i q_i\\) 达阈值封 bar，收益用 bar 内第一笔到最后一笔（或 VWAP 差，对象不同）。阈值按日或按滚动分位，使每天 bar 数大致稳定——否则危机日 bar 暴增，又回到异质。</p><p><strong>诊断。</strong> 墙钟收益 vs 业务时间收益的峰度、ACF、季节。Ané–Geman：适当时钟下无条件更近正态。GARCH 的 \\(\\alpha+\\beta\\) 常下降——部分「持续」被时钟吸收。</p><p><strong>RV。</strong> 在业务格上算 RV，积分的是业务时间里的二次变差，再映射回日历日要声明。与核估计混用时钟会错单位。隔夜仍单独，业务时间不跨会话累计除非明确。</p><h3 id="对冲与回归" tabindex="-1">对冲与回归 <a class="header-anchor" href="#对冲与回归" aria-label="Permalink to &quot;对冲与回归&quot;">​</a></h3><p>已实现 \\(\\beta\\) 在业务时间格上：共同活动对齐更好，可能减轻部分异步（都在忙时更新）。但不能替代刷新：一只没成交时金额时钟不会替它更新。业务时间不是同步规则。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>从属：日历上的厚尾来自随机的 \\(\\theta(t)\\) 混合。给定 \\(\\theta\\)，增量更近高斯。机制把异方差的一部分写成时间变形，而不是 \\(\\sigma_t\\) 过程。GARCH 把异方差写在墙钟 \\(\\sigma_t\\)；两者可同时真：即使业务时间较齐，仍可有剩余 GARCH。经验上时钟吃掉季节与部分聚集，不是全部。</p><p>噪声：业务格内若仍含多笔弹跳，格收益仍有 \\(\\varepsilon\\)。格越粗，噪声相对下降，类似降频。阈值太大则分辨率丢、跳被并进一格。阈值是带宽，与 \\(K\\)、\\(k\\)、\\(H\\) 同类。</p><p><span class="marginnote">用未来成交量定当天阈值（让每天恰好 50 根）有轻微前视。应用昨日分位或固定金额。回测非法的时钟与线性插值前视同类。</span></p><h3 id="到预测损失的交接" tabindex="-1">到预测损失的交接 <a class="header-anchor" href="#到预测损失的交接" aria-label="Permalink to &quot;到预测损失的交接&quot;">​</a></h3><p>HAR 预测的是日历日 RV 还是下一根 dollar bar 的方差，损失必须定义在同一时钟。用墙钟 QLIKE 去评业务时间模型，是评错对象。下一课把 Patton 纪律搬到高频：代理、损失、时钟三者锁定。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>停牌时 \\(\\theta\\) 冻结，墙钟仍走，从属解释断掉。拍卖、开收盘批量不是点过程从属的理想样本。外汇 24h 的「日」要定义会话切 \\(\\theta\\)。</p><p>工程：盘中切片、齐次建模用 dollar/volume bars；监管与日频 HAR 用墙钟。报告阈值与是否前视。不要把业务时间相关当成日历相关去做隔夜对冲。不要用 tick bars 当无噪声观测。最后一课：高频预测的损失。</p>',24)),(e(),s(h,null,{default:r(()=>[E(o,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20WALL%5B%22%E5%A2%99%E9%92%9F%20t%22%5D%20--%3E%20SEAS%5B%22%E5%AD%A3%E8%8A%82%20%2F%20%E5%BF%99%E9%97%B2%E4%B8%8D%E9%BD%90%22%5D%0A%20%20WALL%20--%3E%20TH%5B%22%E7%B4%AF%E8%AE%A1%E6%88%90%E4%BA%A4%E9%87%8F%E6%88%96%E7%AC%94%E6%95%B0%E8%BE%BE%E9%98%88%22%5D%0A%20%20TH%20--%3E%20BT%5B%22%E4%B8%9A%E5%8A%A1%E6%97%B6%E9%97%B4%E6%A0%BC%22%5D%0A%20%20BT%20--%3E%20HOM%5B%22%E5%A2%9E%E9%87%8F%E8%BE%83%E9%BD%90%E6%AC%A1%20%2F%20%E5%B3%B0%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SUB%5B%22%E4%BB%8E%E5%B1%9E%3A%20X_t%20%3D%20W_%CE%B8(t)%22%5D%20--%3E%20BT%0A%20%20HOM%20--%3E%20LOSS%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E6%8D%9F%E5%A4%B1%E5%AE%9A%E4%B9%89%E5%9C%A8%E5%90%8C%E4%B8%80%E6%97%B6%E9%92%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>业务时间把日历变形为活动时钟，从属过程解释部分厚尾与季节。</li><li>Tick/volume/dollar bars 是其离散实现；阈值是带宽，须防前视。</li><li>它不替代噪声修正与刷新同步；GARCH 持续可部分被时钟吸收。</li><li>预测与 RV 的单位必须与时钟一致。</li><li>出处：Mandelbrot and Taylor, <em>Operations Research</em>, 1967；Clark, <em>Econometrica</em>, 1973；Ané and Geman, <em>Journal of Finance</em>, 2000。</li></ul>',2))])}const k=n(c,[["render",p]]);export{f as __pageData,k as default};
